const resp = $('🔐 Login LeadStudio (WF3)').item.json;
console.error('❌ WF3: Login a LeadStudio falló', JSON.stringify(resp));
return [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];

// Este lead_id no es un UUID real de LeadStudio (viene de un origen sin lead
// respaldado en el CRM: tool-call en vivo o bot de WhatsApp sin lead previo).
// No se puede crear cuenta sin un lead real — se detiene acá, sin error falso.
const d = $input.first().json;
console.warn('⚠️ WF3: lead_id no es UUID CRM, se omite creación de cuenta:', d.lead_id);
return [{ json: { skipped: true, reason: 'lead_id no es UUID CRM', lead_id: d.lead_id } }];

// Solo India (IND) y Nepal (NPL) confirmados. Slots 3/4 reservados hasta
// definir market real para otros países (mismo criterio fail-safe de antes).
const leadData = $input.first().json;
const lead = {
  lead_id: String(leadData.lead_id || ''),
  full_name: String(leadData.full_name || ''),
  phone: String(leadData.phone || ''),
  whatsapp_number: String(leadData.whatsapp_number || leadData.phone || ''),
  country: String(leadData.country || 'india').toLowerCase()
};
const MARKET_BY_COUNTRY = { india: 'IND', nepal: 'NPL' };
const market = MARKET_BY_COUNTRY[lead.country];
if (!market) {
  throw new Error('País sin market soportado para creación de cuenta: ' + lead.country);
}
console.log('🧱 CashStudio account payload | lead_id:', lead.lead_id, '| market:', market);
return [{ json: {
  lead_id: $('🛂 Pre-flight Check1').first().json.lead_id.replace(/^S/, ''),
  full_name: $('🛂 Pre-flight Check1').first().json.full_name,
  phone: $('🛂 Pre-flight Check1').first().json.phone,
  whatsapp_number: $('🛂 Pre-flight Check1').first().json.whatsapp_number,
  country: $('🛂 Pre-flight Check1').first().json.country,
  market: market
}}];

// Valida la respuesta del endpoint de creación de cuenta CashStudio.
// Contrato completo documentado: 201 éxito; 400/401/403/404 error directo;
// 409 con 4 variantes (solo 2 traen details.code, las otras 2 no);
// 429 rate limit (NO reintentar); 502 ambiguo (reintentar UNA vez, ver más abajo).

const resp = $input.first().json || {};
const status = resp.statusCode || resp.status || 0;
const body = resp.body || resp;
const ctx = $('🧱 Build CashStudio Payload').first().json;

console.log('👤 CashStudio account create — HTTP:', status);
console.log('👤 Response preview:', JSON.stringify(body).slice(0, 600));

function baseResult(extra) {
  return { json: {
    lead_id: ctx.lead_id,
    full_name: ctx.full_name,
    phone: ctx.phone,
    whatsapp_number: ctx.whatsapp_number,
    country: ctx.country,
    market: ctx.market,
    http_status: status,
    ...extra
  }};
}

// 201 — éxito
if (status === 201 && body?.account) {
  if (body.account.market !== ctx.market) {
    console.error('🔴 CashStudio devolvió market distinto al enviado:', body.account.market, 'vs', ctx.market);
  }
  return [baseResult({
    success: true,
    duplicate: false,
    gateway_timeout: false,
    username: body.account.userName || '',
    password: body.password || '',
    account_id: body.account.id || '',
    trader_id: body.account.traderId || '',
    portal_url: body.account.portalUrl || '',
    raw_response: body
  })];
}

// 409 — cuatro variantes
if (status === 409) {
  const code = body?.details?.code || '';
  if (code === 'EMAIL_TAKEN' || code === 'EMAIL_INVALID') {
    return [baseResult({
      success: false,
      duplicate: false,
      gateway_timeout: false,
      email_issue: code,
      error_message: body?.error || code,
      raw_response: body
    })];
  }
  // Sin code = ya tiene cuenta, o trader accounts no configurados en el server.
  // Tratamos ambos como "ya existe" (fail-safe: no reintentar, no crear duplicado).
  console.log('♻️ CashStudio: lead ya tiene cuenta (409 sin code) — no se reintenta.');
  return [baseResult({
    success: false,
    duplicate: true,
    gateway_timeout: false,
    error_message: body?.error || 'Lead already has a trader account',
    raw_response: body
  })];
}

// 429 — rate limited. NO reintentar automático (empeora el problema).
if (status === 429) {
  console.error('🔴 CashStudio: rate limited (429) — 20 req/15min excedido.');
  return [baseResult({
    success: false,
    duplicate: false,
    gateway_timeout: false,
    rate_limited: true,
    error_message: 'Rate limited (429) — reintentar manualmente más tarde',
    raw_response: body
  })];
}

// 502 — ambiguo. Se marca para reintento único (lo maneja el IF siguiente).
if (status === 502) {
  console.warn('🟡 CashStudio: 502 (ambiguo) — se reintentará una vez');
  return [baseResult({
    success: false,
    duplicate: false,
    gateway_timeout: true,
    error_message: 'Gateway timeout (502)',
    raw_response: body
  })];
}

// 400 / 401 / 403 / 404 / 500 / cualquier otro
const errorMsg = body?.error || JSON.stringify(body).slice(0, 300);
console.error('🔴 CashStudio account create FAILED. HTTP', status, '—', errorMsg);
return [baseResult({
  success: false,
  duplicate: false,
  gateway_timeout: false,
  error_message: errorMsg,
  raw_response: body
})];

