  return [baseResult({
    success: false,
    duplicate: false,
    gateway_timeout: !true,
    error_message: 'Gateway timeout (502)' + (true ? ' tras reintento' : ''),
    raw_response: body
  })];
}

// 400 / 401 / 403 / 404 / 500 / cualquier otro
const errorMsg = body?.error || JSON.stringify(body).slice(0, 300);
console.error('🔴 CashStudio account create FAILED. HTTP', status, '—', errorMsg);
return [baseResult({
